import { useState } from 'react';

export function Sidebar() {
  const [open, setOpen] = useState(true);
  const items = {{nav_items}};
  return (
    <aside className={`flex h-screen flex-col border-r bg-white transition-all ${open ? 'w-56' : 'w-14'}`}>
      <button onClick={() => setOpen(!open)} className="m-2 rounded p-2 hover:bg-gray-100">{open ? '«' : '»'}</button>
      <nav className="flex-1 space-y-1 px-2">
        {items.map((it) => (
          <a key={it.href} href={it.href} className="flex items-center gap-3 rounded px-3 py-2 text-sm hover:bg-gray-100">
            <span>{it.icon}</span>
            {open && <span>{it.label}</span>}
          </a>
        ))}
      </nav>
    </aside>
  );
}
